def _make_public_id(kind: str, row_id: int) -> str:
    return f"{PUBLIC_ID_PREFIX[kind]}-{row_id:06d}"


def _ensure_public_id(db, kind: str, obj) -> str:
    """Obyektga ommaviy ID beradi (agar hali bo'lmasa). ID ichki
    raqamdan hosil qilinadi - shuning uchun hech qachon takrorlanmaydi."""
    if not getattr(obj, "public_id", None):
        obj.public_id = _make_public_id(kind, obj.id)
    return obj.public_id


def backfill_missing_ids(db, kind: str, model) -> None:
    """ID'siz qolgan yozuvlarga ID beradi. Ro'yxat ochilganda
    chaqiriladi: odatda hech nima topmaydi (indeksli bitta so'rov),
    lekin bazaga tashqaridan qo'shilgan yozuv ham ID'siz qolmaydi."""
    try:
        rows = db.query(model).filter(model.public_id.is_(None)).all()
        if not rows:
            return
        for r in rows:
            r.public_id = _make_public_id(kind, r.id)
        db.commit()
    except Exception:
        db.rollback()


def _backfill_public_ids():
    """Ilova ishga tushganda ID'siz qolgan eski yozuvlarni to'ldiradi."""
    from database import SessionLocal
    pairs = [
        ("student", models.Student), ("parent", models.Parent),
        ("user", models.User), ("lead", models.Lead),
        ("group", models.Group), ("payment", models.Payment),
        ("contract", models.Contract),
    ]
    db = SessionLocal()
    try:
        for kind, model in pairs:
            try:
                rows = db.query(model).filter(model.public_id.is_(None)).all()
            except Exception:
                continue
            for r in rows:
                r.public_id = _make_public_id(kind, r.id)
            if rows:
                db.commit()
    except Exception:
        db.rollback()
    finally:
        db.close()


# =====================================================================
#  SXEMA TAYYORLASH — ENDI FAQAT BIR MARTA
#
#  Ilgari har sovuq startda ~100 ta ALTER urinishi bazaga qatnardi —
#  server uzoq regionda tursa bu 20-30 soniyaga cho'zilib, so'rovlar
#  504 bilan uzilardi. Endi hammasi bir marta bajarilib, bazaga tamg'a
#  (stamp) yoziladi; keyingi startlar 1 ta so'rov bilan o'tib ketadi.
#
#  MUHIM: _ensure_new_columns yoki migrations.MIGRATIONS ga yangi
#  narsa qo'shsangiz — SCHEMA_STAMP satrini ham yangilang, aks holda
#  yangi ustunlar jonli bazaga yetib bormaydi.
# =====================================================================
SCHEMA_STAMP = "stamp_2026_08_04b"


def _schema_bootstrap():
    db = SessionLocal()
    try:
        try:
            done = db.query(models.SchemaMigration).filter(
                models.SchemaMigration.version == SCHEMA_STAMP).first()
        except Exception:
            done = None
        if done:
            return
        _ensure_new_columns()
        _backfill_public_ids()
        migrations.run(db)
        db.add(models.SchemaMigration(version=SCHEMA_STAMP))
        db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
    finally:
        db.close()


_schema_bootstrap()

app = FastAPI(title="JonyOS API — Jony Academy boshqaruv tizimi")


@app.exception_handler(Exception)
async def _unhandled_error(request: Request, exc: Exception):
    """Kutilmagan xato: foydalanuvchi aytishini kutmasdan error_logs
    jadvaliga yozamiz — asoschi Audit bo'limida ko'radi."""
    try:
        import traceback
        edb = SessionLocal()
        edb.add(models.ErrorLog(
            path=str(request.url.path)[:200],
            method=request.method,
            detail="".join(traceback.format_exception(
                type(exc), exc, exc.__traceback__))[-4000:],
        ))
        edb.commit()
        edb.close()
    except Exception:
        pass
    return JSONResponse(status_code=500, content={
        "detail": "Serverda kutilmagan xato. Bu xato qayd etildi va "
                  "tez orada ko'rib chiqiladi."})

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],  # tighten before real deployment
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.get("/api/_bootstrap")
def bootstrap(key: str, db: Session = Depends(get_db)):
    """One-time setup: creates the first admin account on a fresh database.
    Gated by the deploy secret so it's safe to leave live - it no-ops once
    any user exists."""
    if key != SECRET_KEY:
        raise HTTPException(403, "Forbidden")
    if db.query(models.User).count() > 0:
        return {"ok": False, "message": "Already initialized"}
    admin = models.User(
        username="admin",
        password_hash=hash_password("ChangeMe123!"),
        full_name="Administrator",
        role=roles.FOUNDER,
        branch_id=None,
    )
    db.add(admin)
    db.commit()
    return {"ok": True, "message": "Admin user created"}


def student_balance(db: Session, student_id: int) -> float:
    total = (
        db.query(func.coalesce(func.sum(models.Payment.amount), 0.0))
        .filter(models.Payment.student_id == student_id)
        .scalar()
    )
    return float(total or 0)


def to_student_out(db: Session, s: models.Student) -> schemas.StudentOut:
    data = schemas.StudentOut.model_validate(s)
    data.balance = student_balance(db, s.id)
    return data


def _sync_student_left_date(s: models.Student):
    """Ketgan sanani statusdan avtomatik chiqaramiz - hech kim uni qo'lda
    kiritmaydi, shuning uchun LTV hisoboti hech qachon "esdan chiqib"
    qolmaydi. "archived" = markazni tark etgan."""
    if s.status == "archived":
        if not s.left_date:
            s.left_date = date.today()
    else:
        # Qaytib keldi - hisobot uni yana faol mijoz deb ko'rsin.
        s.left_date = None


def _sync_teacher_left_date(t: models.Teacher):
    """Ustoz ishdan ketgan/qaytgan sanasini is_active'dan avtomatik olamiz."""
    if not t.hired_date:
        t.hired_date = date.today()
    if t.is_active:
        t.left_date = None
    elif not t.left_date:
        t.left_date = date.today()


def _months_between(start: date, end: date) -> float:
    """Ikki sana orasidagi oylar soni (kasrli). LTV va retention shu
    o'lchovda ko'rsatiladi - "3.5 oy" degani odamga tushunarli."""
    if not start or not end or end < start:
        return 0.0
    return round((end - start).days / 30.44, 1)


def scope_to_branch(query, model, user: models.User, branch_id=None):
    """Filialga bo'yicha cheklash.

    Ikki xil cheklash bor va ular aralashmasligi kerak:
      1) HUQUQ - filialga bog'langan xodim faqat o'z filialini ko'radi.
         Buni hech kim aylanib o'ta olmaydi.
      2) FILTR - butun tashkilotni ko'radigan odam (asoschi, HR, SMM)
         istagan filialni alohida ko'rmoqchi bo'lsa, branch_id beradi.
    """
    if user.role not in tuple(roles.ORG_WIDE_ROLES) and user.branch_id:
        # Huquq cheklovi: o'z filiali. So'ralgan filial boshqa bo'lsa ham
        # baribir o'ziniki qaytadi.
        return query.filter(model.branch_id == user.branch_id)
    if branch_id and hasattr(model, "branch_id"):
        return query.filter(model.branch_id == branch_id)
    return query


def can_see_all_branches(user: models.User) -> bool:
    """Butun tashkilotni ko'radimi yoki bitta filialgami."""
    return user.role in tuple(roles.ORG_WIDE_ROLES) or not user.branch_id


# ---------------------------------------------------------------- Auth ----
def _login_guard(db: Session, username: str, ip: str = ""):
    """Brute-force himoyasi: 15 daqiqada 5 marta xato parol —
    vaqtincha blok. Muvaffaqiyatli kirish hisoblagichni tozalaydi."""
    since = datetime.utcnow() - timedelta(minutes=roles.LOGIN_WINDOW_MIN)
    fails = db.query(models.LoginAttempt).filter(
        models.LoginAttempt.username == username,
        models.LoginAttempt.success == 0,
        models.LoginAttempt.created_at >= since).count()
    if fails >= roles.LOGIN_MAX_FAILS:
        raise HTTPException(
            429, f"Ko'p noto'g'ri urinish. {roles.LOGIN_WINDOW_MIN} "
                 "daqiqadan keyin qayta urinib ko'ring.")


def _login_record(db: Session, username: str, ip: str, success: bool):
    try:
        db.add(models.LoginAttempt(username=username, ip=ip or None,
                                   success=1 if success else 0))
        if success:
            # Muvaffaqiyatdan keyin eski xatolar hisobga kirmasin
            db.query(models.LoginAttempt).filter(
                models.LoginAttempt.username == username,
                models.LoginAttempt.success == 0).delete()
        db.commit()
    except Exception:
        db.rollback()


@app.post("/api/auth/login", response_model=schemas.Token)
def login(payload: schemas.LoginRequest, request: Request,
          db: Session = Depends(get_db)):
    ip = (request.headers.get("x-forwarded-for") or
          (request.client.host if request.client else "") or "")[:64]
    _login_guard(db, payload.username, ip)
    user = db.query(models.User).filter(models.User.username == payload.username).first()
    if not user or not verify_password(payload.password, user.password_hash):
        _login_record(db, payload.username, ip, False)
        raise HTTPException(status_code=401, detail="Login yoki parol noto'g'ri")
    if not user.is_active:
        raise HTTPException(status_code=401, detail="Bu hisob faolsizlantirilgan")
    _login_record(db, payload.username, ip, True)
    token = create_access_token({"sub": user.username})
    # Oy boshida birinchi kirishda oylik to'lovlar avtomat yechiladi
    try:
        _founder_name_fix(db)
        _ensure_month_charges(db)
    except Exception:
        pass
    return schemas.Token(
        access_token=token, role=user.role, full_name=user.full_name, branch_id=user.branch_id
    )


@app.put("/api/auth/recovery-code")
def set_recovery_code(payload: schemas.RecoverySetIn,
                      db: Session = Depends(get_db),
                      user: models.User = Depends(require_role(roles.FOUNDER))):
    """Asoschi favqulodda tiklash kodini o'rnatadi. Parol unutilsa,
    shu kod bilan tiklanadi — tizim egasiz qolib ketmaydi."""
    if not verify_password(payload.current_password, user.password_hash):
        raise HTTPException(400, "Joriy parol noto'g'ri")
    code = (payload.recovery_code or "").strip()
    if len(code) < 10:
        raise HTTPException(400, "Tiklash kodi kamida 10 belgi bo'lsin")
    user.recovery_hash = hash_password(code)
    db.commit()
    audit.log(db, user, entity="user", action="recovery_set",
              entity_id=user.id, entity_label=user.full_name)
    db.commit()
    return {"ok": True}


@app.post("/api/auth/recover")
def recover_password(payload: schemas.RecoverIn, request: Request,
                     db: Session = Depends(get_db)):
    """Parolni tiklash kodi bilan almashtirish (faqat asoschi hisobi).
    Login himoyasi bilan bir xil blok qoidasi amal qiladi."""
    ip = (request.headers.get("x-forwarded-for") or
          (request.client.host if request.client else "") or "")[:64]
    _login_guard(db, payload.username, ip)
    user = db.query(models.User).filter(
        models.User.username == payload.username,
        models.User.role == roles.FOUNDER).first()
    if not user or not user.recovery_hash or \
            not verify_password(payload.recovery_code, user.recovery_hash):
        _login_record(db, payload.username, ip, False)
        raise HTTPException(401, "Login yoki tiklash kodi noto'g'ri")
    if not roles.password_ok(payload.new_password):
        raise HTTPException(400, roles.PASSWORD_RULE_TEXT)
    user.password_hash = hash_password(payload.new_password)
    db.commit()
    _login_record(db, payload.username, ip, True)
    audit.log(db, None, entity="user", action="recover",
              entity_id=user.id, entity_label=user.full_name,
              note="parol tiklash kodi bilan almashtirildi")
    db.commit()
    return {"ok": True}


@app.get("/api/auth/me", response_model=schemas.UserOut)
def me(user: models.User = Depends(get_current_user)):
    return user


@app.put("/api/auth/me/password")
def change_own_password(
    payload: schemas.ChangePasswordRequest,
    db: Session = Depends(get_db),
    user: models.User = Depends(get_current_user),
):
    if not verify_password(payload.current_password, user.password_hash):
        raise HTTPException(status_code=400, detail="Joriy parol noto'g'ri")
    if not roles.password_ok(payload.new_password):
        raise HTTPException(status_code=400, detail=roles.PASSWORD_RULE_TEXT)
    user.password_hash = hash_password(payload.new_password)
    db.commit()
    return {"ok": True}


