@app.get("/api/gamification/analytics")
def gamification_analytics(
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.XP_ADMIN, *roles.FINANCE_ACCESS)),
):
    """CEO uchun: filial, guruh va ustoz kesimida XP, hamda XP bilan
    davomat va natija o'rtasidagi bog'liqlik."""
    gam = {g.student_id: g for g in db.query(models.StudentGamification).all()}
    students = db.query(models.Student).filter(
        models.Student.status.in_(["active", "trial"])).all()
    groups = {g.id: g for g in db.query(models.Group).all()}
    branches = {b.id: b.name for b in db.query(models.Branch).all()}
    teachers = {t.id: t.full_name for t in db.query(models.Teacher).all()}

    def agg(key_fn, label_fn):
        out: dict = {}
        for s in students:
            k = key_fn(s)
            if k is None:
                continue
            row = out.setdefault(k, {"students": 0, "xp": 0.0})
            row["students"] += 1
            row["xp"] += (gam[s.id].lifetime_xp or 0) if s.id in gam else 0
        return sorted([{
            "key": k, "label": label_fn(k),
            "students": v["students"],
            "total_xp": round(v["xp"], 1),
            "avg_xp": round(v["xp"] / v["students"], 1) if v["students"] else 0,
        } for k, v in out.items()], key=lambda r: -r["avg_xp"])

    by_branch = agg(lambda s: s.branch_id, lambda k: branches.get(k, "—"))
    by_group = agg(lambda s: s.group_id,
                   lambda k: groups[k].name if k in groups else "—")
    by_teacher = agg(
        lambda s: groups[s.group_id].teacher_id if s.group_id in groups else None,
        lambda k: teachers.get(k, "—"))

    # XP va davomat bog'liqligi
    pairs = []
    for s in students:
        g = gam.get(s.id)
        if not g:
            continue
        att = (db.query(models.Attendance)
               .filter(models.Attendance.student_id == s.id).all())
        if not att:
            continue
        rate = sum(1 for a in att if a.present) / len(att) * 100
        pairs.append((g.lifetime_xp or 0, rate))
    corr = None
    if len(pairs) >= 3:
        n = len(pairs)
        mx = sum(p[0] for p in pairs) / n
        my = sum(p[1] for p in pairs) / n
        num = sum((p[0] - mx) * (p[1] - my) for p in pairs)
        dx = sum((p[0] - mx) ** 2 for p in pairs) ** 0.5
        dy = sum((p[1] - my) ** 2 for p in pairs) ** 0.5
        corr = round(num / (dx * dy), 2) if dx and dy else None

    # Ustozlar qancha qo'lda XP berdi
    manual: dict = {}
    for t in (db.query(models.XpTransaction)
              .filter(models.XpTransaction.source_type == "manual").all()):
        if t.awarded_by_user_id:
            manual[t.awarded_by_user_id] = manual.get(t.awarded_by_user_id, 0) \
                + (t.amount or 0)
    unames = {u.id: u.full_name for u in db.query(models.User).all()}

    return {
        "by_branch": by_branch,
        "by_group": by_group[:20],
        "weakest_groups": by_group[-5:][::-1] if len(by_group) > 5 else [],
        "by_teacher": by_teacher,
        "attendance_correlation": corr,
        "correlation_hint": ("1 ga yaqin bo'lsa — XP ko'p bo'lgan o'quvchi "
                             "darsga ham ko'p keladi."),
        "manual_by_user": sorted([{
            "user": unames.get(k, "—"), "xp": round(v, 1)
        } for k, v in manual.items()], key=lambda r: -r["xp"])[:10],
    }


# =====================================================================
#  DARS BAHOLASH
#
#  Ikkita jadval: birinchi dars va asosiy dars, ikkalasi ham 100 balldan.
#  Baholovchi faqat "Fakt" ustunini to'ldiradi — jami va foiz o'zi
#  hisoblanadi.
#
#  Natija bekorga qolmaydi: ustozning skill_score'iga tushadi, ya'ni
#  karyera darajasining shartlariga bevosita ta'sir qiladi (ustozlikni
#  boshlash uchun 50+, Head teacher uchun 70+ ball).
# =====================================================================
def _seed_rubrics(db: Session) -> None:
    have = {r.key for r in db.query(models.LessonRubric).all()}
    added = False
    for key, name, desc in roles.RUBRICS:
        if key in have:
            continue
        db.add(models.LessonRubric(key=key, name=name, description=desc,
                                   is_active=1))
        added = True
    if added:
        db.commit()

    for key, items in roles.RUBRIC_ITEMS.items():
        existing = (db.query(models.RubricCriterion)
                    .filter(models.RubricCriterion.rubric_key == key).count())
        if existing:
            continue          # HR tahrirlagan bo'lishi mumkin — tegmaymiz
        for no, text, points in items:
            db.add(models.RubricCriterion(
                rubric_key=key, order_no=no, text=text, points=points,
                is_active=1))
        db.commit()


def _criteria(db: Session, key: str) -> list:
    return (db.query(models.RubricCriterion)
            .filter(models.RubricCriterion.rubric_key == key,
                    models.RubricCriterion.is_active == 1)
            .order_by(models.RubricCriterion.order_no,
                      models.RubricCriterion.id).all())


def _refresh_skill_score(db: Session, teacher_id: int) -> float | None:
    """Ustozning mahorat balli — oxirgi ASOSIY dars baholashining foizi.

    Nega oxirgisi: mahorat o'zgaradi, o'rtacha esa eski, allaqachon
    tuzatilgan kamchilikni yillar davomida sudrab yuradi."""
    last = (db.query(models.LessonObservation)
            .filter(models.LessonObservation.teacher_id == teacher_id,
                    models.LessonObservation.rubric_key == roles.RUBRIC_MAIN)
            .order_by(models.LessonObservation.date.desc(),
                      models.LessonObservation.id.desc()).first())
    if not last:
        return None
    t = db.query(models.Teacher).get(teacher_id)
    if t:
        t.skill_score = last.percent
    return last.percent


@app.get("/api/rubrics")
def list_rubrics(
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.OBSERVATION_ACCESS)),
):
    """Baholash jadvallari va ularning mezonlari."""
    _seed_rubrics(db)
    out = []
    for r in (db.query(models.LessonRubric)
              .order_by(models.LessonRubric.id).all()):
        items = _criteria(db, r.key)
        out.append({
            "key": r.key, "name": r.name, "description": r.description,
            "is_active": bool(r.is_active),
            "max_total": round(sum(c.points or 0 for c in items), 1),
            "criteria": [{
                "id": c.id, "no": c.order_no, "text": c.text,
                "points": c.points or 0,
            } for c in items],
        })
    return {
        "rows": out,
        "targets": [{"key": k, "label": lbl}
                    for k, lbl in roles.OBSERVATION_TARGETS],
        "pass_score": roles.TEACHER_MIN_SKILL,
        "head_score": roles.HEAD_MIN_SKILL,
        "can_edit": user.role in roles.GRADE_ADMIN,
        "hint": ("Faqat \"Fakt\" ustunini to'ldirasiz — jami va foiz o'zi "
                 f"hisoblanadi. Ustozlikni boshlash uchun "
                 f"{round(roles.TEACHER_MIN_SKILL)}+ ball, Head teacher "
                 f"uchun {round(roles.HEAD_MIN_SKILL)}+ ball kerak."),
    }


@app.put("/api/rubrics/criteria/{cid}")
def update_criterion(
    cid: int,
    payload: schemas.CriterionUpdate,
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.GRADE_ADMIN)),
):
    c = db.query(models.RubricCriterion).get(cid)
    if not c:
        raise HTTPException(404, "Mezon topilmadi")
    given = payload.model_dump(exclude_unset=True)
    for k, v in given.items():
        setattr(c, k, 1 if k == "is_active" and v else
                (0 if k == "is_active" else v))
    db.commit()
    audit.log(db, user, entity="rubric", action="update", entity_id=c.id,
              entity_label=c.text[:60], new_value=str(given),
              note="Baholash mezoni o'zgartirildi")
    db.commit()
    items = _criteria(db, c.rubric_key)
    return {"ok": True,
            "max_total": round(sum(x.points or 0 for x in items), 1)}


@app.post("/api/rubrics/criteria")
def add_criterion(
    payload: schemas.CriterionCreate,
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.GRADE_ADMIN)),
):
    items = _criteria(db, payload.rubric_key)
    c = models.RubricCriterion(
        rubric_key=payload.rubric_key, text=payload.text,
        points=payload.points,
        order_no=(max([x.order_no or 0 for x in items], default=0) + 1),
        is_active=1)
    db.add(c)
    db.commit()
    return {"ok": True, "id": c.id}


@app.post("/api/observations")
def create_observation(
    payload: schemas.ObservationCreate,
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.OBSERVATION_ACCESS)),
):
    """Baholashni saqlaydi. Jami va foiz SERVERDA hisoblanadi — qo'lda
    yozib bo'lmaydi."""
    if payload.rubric_key not in roles.RUBRIC_LABELS:
        raise HTTPException(400, "Bunday baholash jadvali yo'q")
    if payload.target_type == "teacher" and not payload.teacher_id:
        raise HTTPException(400, "Ustozni tanlang")
    if payload.target_type == "candidate" and not payload.candidate_id:
        raise HTTPException(400, "Nomzodni tanlang")

    items = {c.id: c for c in _criteria(db, payload.rubric_key)}
    max_total = round(sum(c.points or 0 for c in items.values()), 1)

    total = 0.0
    clean = []
    for s in payload.scores:
        c = items.get(s.criterion_id)
        if not c:
            continue
        # Fakt mezon balidan oshmaydi va manfiy bo'lmaydi
        fact = max(0.0, min(float(s.fact or 0), float(c.points or 0)))
        total += fact
        clean.append((c.id, fact, s.note))

    percent = round(total / max_total * 100, 1) if max_total else 0.0
    band, _lbl, _tone = roles.rubric_band(percent)

    t = db.query(models.Teacher).get(payload.teacher_id) \
        if payload.teacher_id else None

    # Bosqich: berilmagan bo'lsa o'zi aniqlanadi. Nomzodning birinchi
    # baholashi "o'z holicha", ikkinchisi "tushuntirilgandan keyin".
    prev = (db.query(models.LessonObservation)
            .filter(models.LessonObservation.candidate_id
                    == payload.candidate_id)
            .count() if payload.candidate_id else 0)
    stage = payload.stage
    if not stage:
        if payload.candidate_id:
            stage = ("before" if prev == 0
                     else "coached" if prev == 1 else "extra")
        else:
            stage = "extra"

    obs = models.LessonObservation(
        rubric_key=payload.rubric_key,
        target_type=payload.target_type,
        stage=stage, attempt=prev + 1,
        teacher_id=payload.teacher_id,
        candidate_id=payload.candidate_id,
        group_id=payload.group_id,
        branch_id=t.branch_id if t else None,
        date=payload.date or date.today(),
        total=round(total, 1), max_total=max_total, percent=percent,
        band=band, strengths=payload.strengths,
        weaknesses=payload.weaknesses, note=payload.note,
        observer=user.full_name, observer_id=user.id)
    db.add(obs)
    db.flush()
    for cid, fact, note in clean:
        db.add(models.ObservationScore(observation_id=obs.id,
                                       criterion_id=cid, fact=fact,
                                       note=note))
    db.commit()

    # Natija ishga tushadi: ustozning mahorat balli, nomzodning
    # sinov darsi bali.
    if payload.teacher_id:
        _refresh_skill_score(db, payload.teacher_id)
        db.commit()
    if payload.candidate_id:
        cand = db.query(models.Candidate).get(payload.candidate_id)
        if cand:
            cand.trial_score = percent
            db.commit()

    return {
        "ok": True, "id": obs.id,
        "total": obs.total, "max_total": max_total, "percent": percent,
        "band": band, "band_label": roles.rubric_band(percent)[1],
        "passed": percent >= roles.TEACHER_MIN_SKILL,
        "stage": obs.stage,
        "stage_label": roles.STAGE_LABELS.get(obs.stage or "", "Baholash"),
        "attempt": obs.attempt,
    }


def _observation_out(db: Session, o: models.LessonObservation,
                     full: bool = False) -> dict:
    _k, label, tone = roles.rubric_band(o.percent or 0)
    row = {
        "id": o.id, "rubric_key": o.rubric_key,
        "rubric": roles.RUBRIC_LABELS.get(o.rubric_key, o.rubric_key),
        "target_type": o.target_type,
        "stage": o.stage,
        "stage_label": roles.STAGE_LABELS.get(o.stage or "", "Baholash"),
        "stage_tone": roles.STAGE_TONE.get(o.stage or "", "slate"),
        "attempt": o.attempt or 1,
        "teacher_id": o.teacher_id, "candidate_id": o.candidate_id,
        "teacher": o.teacher.full_name if o.teacher else None,
        "date": o.date.isoformat() if o.date else None,
        "total": o.total or 0, "max_total": o.max_total or 0,
        "percent": o.percent or 0,
        "band": o.band, "band_label": label, "tone": tone,
        "observer": o.observer,
        "strengths": o.strengths, "weaknesses": o.weaknesses,
        "note": o.note,
    }
    if full:
        crit = {c.id: c for c in db.query(models.RubricCriterion).all()}
        row["scores"] = sorted([{
            "criterion_id": s.criterion_id,
            "no": crit[s.criterion_id].order_no if s.criterion_id in crit else 0,
            "text": crit[s.criterion_id].text if s.criterion_id in crit else "—",
            "points": crit[s.criterion_id].points if s.criterion_id in crit else 0,
            "fact": s.fact or 0,
            "note": s.note,
        } for s in o.scores], key=lambda r: r["no"])
    return row


@app.get("/api/observations")
def list_observations(
    teacher_id: int | None = None,
    candidate_id: int | None = None,
    rubric_key: str | None = None,
    db: Session = Depends(get_db),
    user=Depends(get_current_user),
):
    """Baholashlar ro'yxati. Ustoz o'zinikini ko'ra oladi."""
    mine = _teacher_of_user(db, user)
    if user.role not in roles.OBSERVATION_ACCESS:
        if not mine or (teacher_id and teacher_id != mine.id):
            raise HTTPException(403, "Bu ma'lumot sizga ko'rinmaydi")
        teacher_id = mine.id

    q = db.query(models.LessonObservation)
    if teacher_id:
        q = q.filter(models.LessonObservation.teacher_id == teacher_id)
    if candidate_id:
        q = q.filter(models.LessonObservation.candidate_id == candidate_id)
    if rubric_key:
        q = q.filter(models.LessonObservation.rubric_key == rubric_key)
    rows = q.order_by(models.LessonObservation.date.desc(),
                      models.LessonObservation.id.desc()).limit(100).all()
    return {
        "rows": [_observation_out(db, o) for o in rows],
        "pass_score": roles.TEACHER_MIN_SKILL,
    }


@app.get("/api/observations/{oid}")
def get_observation(
    oid: int,
    db: Session = Depends(get_db),
    user=Depends(get_current_user),
):
    o = db.query(models.LessonObservation).get(oid)
    if not o:
        raise HTTPException(404, "Topilmadi")
    mine = _teacher_of_user(db, user)
    if user.role not in roles.OBSERVATION_ACCESS and (
            not mine or mine.id != o.teacher_id):
        raise HTTPException(403, "Bu ma'lumot sizga ko'rinmaydi")
    return _observation_out(db, o, full=True)


@app.delete("/api/observations/{oid}")
def delete_observation(
    oid: int,
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.GRADE_ADMIN)),
):
    o = db.query(models.LessonObservation).get(oid)
    if not o:
        raise HTTPException(404, "Topilmadi")
    tid = o.teacher_id
    db.delete(o)
    db.commit()
    if tid:
        _refresh_skill_score(db, tid)
        db.commit()
    return {"ok": True}


# ---------------------------------------------- Nomzodni sinash ----
@app.get("/api/candidates/{cid}/evaluation")
def candidate_evaluation(
    cid: int,
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.OBSERVATION_ACCESS)),
):
    """Nomzodni sinash natijasi: o'z holicha bergan darsi va
    tushuntirilgandan keyingi darsi yonma-yon.

    Eng muhim raqam — IKKALASI ORASIDAGI FARQ. Sust boshlab keskin
    o'sgan odam, yaxshi boshlab qimirlamagandan ko'ra ko'proq narsa
    va'da qiladi: birinchisini o'rgatsa bo'ladi, ikkinchisini yo'q."""
    cand = db.query(models.Candidate).get(cid)
    if not cand:
        raise HTTPException(404, "Nomzod topilmadi")

    rows = (db.query(models.LessonObservation)
            .filter(models.LessonObservation.candidate_id == cid)
            .order_by(models.LessonObservation.attempt,
                      models.LessonObservation.id).all())

    before = next((o for o in rows if o.stage == "before"), None)
    after = next((o for o in rows if o.stage == "coached"), None)

    def brief(o):
        if not o:
            return None
        return _observation_out(db, o)

    delta = None
    band = None
    if before and after:
        delta = round((after.percent or 0) - (before.percent or 0), 1)
        label, tone, advice = roles.growth_band(delta)
        band = {"label": label, "tone": tone, "advice": advice}

    # Mezon-mezon solishtirish: nimani o'rgandi, nima o'zgarmadi
    compare = []
    if before and after:
        crit = {c.id: c for c in db.query(models.RubricCriterion).all()}
        b = {s.criterion_id: s.fact or 0 for s in before.scores}
        a = {s.criterion_id: s.fact or 0 for s in after.scores}
        for cidx in set(list(b) + list(a)):
            c = crit.get(cidx)
            if not c:
                continue
            bv, av = b.get(cidx, 0), a.get(cidx, 0)
            compare.append({
                "criterion_id": cidx, "no": c.order_no, "text": c.text,
                "points": c.points or 0,
                "before": bv, "after": av,
                "delta": round(av - bv, 1),
            })
        compare.sort(key=lambda r: (-r["delta"], r["no"]))

    improved = [r for r in compare if r["delta"] > 0]
    stuck = [r for r in compare
             if r["delta"] <= 0 and r["after"] < (r["points"] or 0)]

    return {
        "candidate_id": cid,
        "full_name": cand.full_name,
        "before": brief(before),
        "after": brief(after),
        "extra": [brief(o) for o in rows if o.stage == "extra"],
        "delta": delta,
        "growth": band,
        "compare": compare,
        "improved": improved[:10],
        "stuck": stuck[:10],
        "pass_score": roles.TEACHER_MIN_SKILL,
        "passed": bool(after and (after.percent or 0)
                       >= roles.TEACHER_MIN_SKILL),
        "stages": [{"key": k, "label": lbl, "tone": t}
                   for k, lbl, t in roles.OBSERVATION_STAGES],
        "next_stage": ("before" if not before
                       else "coached" if not after else "extra"),
        "hint": ("Avval nomzod o'z holicha dars beradi. Keyin mezonlar "
                 "tushuntirilib, qayta baholanadi. Ikkinchi ball emas, "
                 "ORASIDAGI FARQ ko'proq narsani aytadi: odam "
                 "aytilganini qabul qilib o'zgara oladimi."),
    }


def _xp_for_certificate(db: Session, student_id: int, *, kind: str,
                        code: str, cert_no: str | None,
                        by_user: models.User, mode: str = roles.CERT_MODE_DIFF,
                        reason: str | None = None) -> dict:
    """Sertifikat XP'si. Bir sertifikat raqamiga qayta XP berilmaydi.
    Yangi va yuqoriroq natija olinsa — standart holatda faqat FARQI
    beriladi."""
    if cert_no:
        used = (db.query(models.XpTransaction)
                .filter(models.XpTransaction.idempotency_key
                        == f"CERT:{cert_no}").first())
        if used:
            _fraud_alert(db, "cert_reuse", student_id=student_id,
                         user_id=by_user.id, transaction_id=used.id,
                         description=f"Sertifikat raqami qayta ishlatildi: {cert_no}")
            db.commit()
            return {"ok": False, "skipped": True,
                    "reason": "Bu sertifikat raqamiga XP allaqachon berilgan"}

    ladder = roles.CERT_RULES.get(kind, [])
    rule = _xp_rule(db, code)
    if not rule:
        raise HTTPException(400, "Bunday sertifikat qoidasi yo'q")
    value = rule.default_xp or 0

    if mode == roles.CERT_MODE_DIFF and ladder:
        # Shu turdagi eng yuqori oldingi natija
        prev_best = 0
        for old in (db.query(models.XpTransaction)
                    .filter(models.XpTransaction.student_id == student_id,
                            models.XpTransaction.event_code.in_(ladder),
                            models.XpTransaction.is_reversal == 0).all()):
            prev_best = max(prev_best, old.amount or 0)
        if prev_best:
            value = max(0, value - prev_best)
            if value == 0:
                return {"ok": False, "skipped": True,
                        "reason": ("Oldingi sertifikat XP'si bundan yuqori "
                                   "yoki teng — qo'shimcha XP berilmaydi")}

    return award_xp(db, student_id=student_id, event_code=code,
                    amount=value, by_user=by_user,
                    source_type="certificate", reason=reason,
                    idempotency_key=(f"CERT:{cert_no}" if cert_no else None),
                    force=True)


# =====================================================================
#  O'QUV MARKAZ TO'LGANLIGI
#
#  Asoschining eng muhim raqami: markaz o'z sig'imining necha foizini
#  ishlatyapti.
#
#  Sig'im shunday chiqadi: bitta xonaga toq kunlari 2 ta guruh, juft
#  kunlari 2 ta guruh — jami 4 ta. Xona 25 kishilik bo'lsa, bitta xona
#  100 o'quvchi sig'diradi. Hamma xonalar qo'shilib markazning sig'imi
#  bo'ladi.
# =====================================================================
def _room_seats(r: models.Room) -> int:
    return int(r.capacity or roles.DEFAULT_ROOM_SEATS)


def _fill_rows(db: Session, user: models.User, *, branch_id=None,
               level: str = roles.FILL_DEFAULT_LEVEL) -> dict:
    per_room = roles.FILL_GROUPS.get(level, 4)

    rooms = scope_to_branch(db.query(models.Room), models.Room,
                            user, branch_id).filter(
        models.Room.active == 1).all()
    groups = scope_to_branch(db.query(models.Group), models.Group,
                             user, branch_id).all()
    students = scope_to_branch(db.query(models.Student), models.Student,
                               user, branch_id).filter(
        models.Student.status.in_(["active", "trial"])).all()
    branches = {b.id: b.name for b in db.query(models.Branch).all()}
    teachers = {t.id: t for t in db.query(models.Teacher).all()}
    grades = {g.key: g for g in db.query(models.TeacherGrade).all()}

    # O'quvchilar guruh kesimida
    per_group: dict = {}
    for s in students:
        if s.group_id:
            per_group[s.group_id] = per_group.get(s.group_id, 0) + 1

    # ---- Xonalar kesimida ----
    room_rows = []
    for r in rooms:
        seats = _room_seats(r)
        cap = seats * per_room
        in_room = [g for g in groups if g.room_id == r.id]
        odd = sum(1 for g in in_room
                  if roles.day_side(_group_days(g)) in ("odd", "mixed"))
        even = sum(1 for g in in_room
                   if roles.day_side(_group_days(g)) in ("even", "mixed"))
        st = sum(per_group.get(g.id, 0) for g in in_room)
        pct = round(st / cap * 100, 1) if cap else 0.0
        label, tone = roles.fill_grade(pct)
        room_rows.append({
            "room_id": r.id, "name": r.name,
            "branch": branches.get(r.branch_id, "—"),
            "branch_id": r.branch_id,
            "seats": seats,
            "capacity": cap,
            "groups": len(in_room),
            "group_slots": per_room,
            "odd_groups": odd, "even_groups": even,
            "students": st,
            "free": max(0, cap - st),
            "percent": pct,
            "label": label, "tone": tone,
        })
    room_rows.sort(key=lambda r: -r["percent"])

    total_cap = sum(r["capacity"] for r in room_rows)
    total_st = sum(r["students"] for r in room_rows)
    # Xonasi biriktirilmagan guruhlardagi o'quvchilar ham bor —
    # ular sig'imga kirmaydi, lekin markazda o'qiyapti. Buni yashirmay
    # alohida ko'rsatamiz, aks holda foiz yolg'on chiqadi.
    no_room = sum(per_group.get(g.id, 0) for g in groups if not g.room_id)

    # ---- Filiallar kesimida ----
    by_branch: dict = {}
    for r in room_rows:
        b = by_branch.setdefault(r["branch_id"], {
            "branch_id": r["branch_id"],
            "name": branches.get(r["branch_id"], "—"),
            "rooms": 0, "capacity": 0, "students": 0, "groups": 0,
        })
        b["rooms"] += 1
        b["capacity"] += r["capacity"]
        b["students"] += r["students"]
        b["groups"] += r["groups"]
    branch_rows = []
    for b in by_branch.values():
        pct = round(b["students"] / b["capacity"] * 100, 1) \
            if b["capacity"] else 0.0
        label, tone = roles.fill_grade(pct)
        branch_rows.append({**b, "percent": pct, "free":
                            max(0, b["capacity"] - b["students"]),
                            "label": label, "tone": tone,
                            "group_slots": b["rooms"] * per_room})
    branch_rows.sort(key=lambda r: -r["percent"])

    # ---- Ustozlar kesimida ----
    # Ustozning sig'imi: darajasi bo'yicha nechta guruh olib bora oladi,
    # har biri o'zi dars beradigan xonaning sig'imicha.
    room_by_id = {r.id: r for r in rooms}
    teacher_rows = []
    for t in teachers.values():
        if t.is_active == 0:
            continue
        mine = [g for g in groups if g.teacher_id == t.id]
        if not mine and branch_id and t.branch_id != branch_id:
            continue
        gr = grades.get(t.grade or "")
        max_groups = (t.max_groups or (gr.max_groups if gr else None)
                      or roles.TEACHER_MAX_GROUPS)
        # O'rtacha xona sig'imi: o'zi ishlaydigan xonalar bo'yicha
        seats_list = [_room_seats(room_by_id[g.room_id])
                      for g in mine if g.room_id in room_by_id]
        seats = (round(sum(seats_list) / len(seats_list)) if seats_list
                 else roles.DEFAULT_ROOM_SEATS)
        cap = max_groups * seats
        st = sum(per_group.get(g.id, 0) for g in mine)
        pct = round(st / cap * 100, 1) if cap else 0.0
        label, tone = roles.fill_grade(pct)
        teacher_rows.append({
            "teacher_id": t.id, "name": t.full_name,
            "branch": branches.get(t.branch_id, "—"),
            "grade": t.grade,
            "grade_label": roles.GRADE_LABELS.get(t.grade or "", "—"),
            "groups": len(mine), "max_groups": max_groups,
            "seats": seats, "capacity": cap, "students": st,
            "free": max(0, cap - st),
            "percent": pct, "label": label, "tone": tone,
        })
    teacher_rows.sort(key=lambda r: -r["percent"])

    percent = round(total_st / total_cap * 100, 1) if total_cap else 0.0
    label, tone = roles.fill_grade(percent)

    # Boshqa darajalarda qanday ko'rinishi
    levels = []
    for key, lbl, g, desc in roles.FILL_LEVELS:
        cap = sum(r["seats"] * g for r in room_rows)
        levels.append({
            "key": key, "label": lbl, "groups_per_room": g,
            "description": desc,
            "capacity": cap,
            "percent": round(total_st / cap * 100, 1) if cap else 0.0,
            "free": max(0, cap - total_st),
            "current": key == level,
        })

    return {
        "level": level,
        "level_label": roles.FILL_LEVEL_LABELS.get(level, level),
        "groups_per_room": per_room,
        "rooms": len(room_rows),
        "capacity": total_cap,
        "students": total_st,
        "students_without_room": no_room,
        "percent": percent,
        "label": label, "tone": tone,
        "free": max(0, total_cap - total_st),
        "group_slots": len(room_rows) * per_room,
        "groups_now": sum(r["groups"] for r in room_rows),
        "levels": levels,
        "by_room": room_rows,
        "by_branch": branch_rows,
        "by_teacher": teacher_rows,
        "hint": ("Sig'im shunday hisoblanadi: bitta xonaga toq kunlari "
                 "2 ta guruh, juft kunlari 2 ta guruh — jami "
                 f"{per_room} ta. Xona {roles.DEFAULT_ROOM_SEATS} "
                 "kishilik bo'lsa, bitta xona "
                 f"{roles.DEFAULT_ROOM_SEATS * per_room} o'quvchi "
                 "sig'diradi."),
    }


@app.get("/api/analytics/fill")
def analytics_fill(
    level: str = roles.FILL_DEFAULT_LEVEL,
    branch_id: int | None = None,
    db: Session = Depends(get_db),
    user=Depends(require_role(*roles.FILL_ACCESS)),
):
    """O'quv markaz qanchaga to'lgan — filial, xona va ustoz kesimida."""
    if level not in roles.FILL_GROUPS:
        level = roles.FILL_DEFAULT_LEVEL
    return _fill_rows(db, user, branch_id=branch_id, level=level)


# =====================================================================
#  SMM: KONTENT QUVURI
#
#  Har bir kontent g'oyadan natijagacha bitta yo'ldan o'tadi.
#  Tasdiqlovchi kontent yo'nalishiga qarab O'ZI aniqlanadi — SMM
#  kimga yuborishni o'ylab o'tirmaydi.
# =====================================================================
def _content_code(c: models.Content) -> str:
    """CONTENT-JA-2026-0048 — atributsiya shu raqamga bog'lanadi."""
    year = (c.planned_date or c.created_at or datetime.utcnow()).year \
        if not isinstance(c.created_at, type(None)) else date.today().year
    return f"CONTENT-JA-{year}-{c.id:04d}"


def _approver_role(c: models.Content) -> str | None:
    """Kontentni kim tasdiqlashi kerak. Narx yoki aksiya bo'lsa —
    sotuv rahbari, rasmiy bayonot bo'lsa — asoschi."""
    if c.goal == "sales" and (c.promo_code or "aksiya" in (c.message or "").lower()):
        return roles.SALES_HEAD
    return roles.APPROVAL_BY_PILLAR.get(c.pillar or "", roles.SMM_MANAGER)


def _content_warnings(db: Session, c: models.Content,
                      today: date | None = None) -> list:
    """Kontentdagi muammolar. Tizim ularni o'zi topadi — SMM
    eslab qolishi shart emas."""
    today = today or date.today()
    out = []
    if c.status in roles.CONTENT_LIVE or c.status == "cancelled":
        if c.status == "published" and not c.post_url:
            out.append({"key": "no_link", "severity": "warn",
                        "text": "Joylandi, lekin havolasi kiritilmagan"})
        return out

    near = c.planned_date and (c.planned_date - today).days <= 1
    if c.planned_date and c.planned_date < today:
        out.append({"key": "late", "severity": "block",
                    "text": f"Muddat o'tdi ({c.planned_date.isoformat()})"})
    if near and c.status in ("idea", "script") and not (c.script or "").strip():
        out.append({"key": "no_script", "severity": "block",
                    "text": "Chiqish vaqti yaqin, ssenariy tayyor emas"})
    if near and c.status in ("shooting", "editing"):
        out.append({"key": "no_design", "severity": "block",
                    "text": "Bugun chiqishi kerak, material hali tayyor emas"})
    if c.needs_consent and not c.consent_ok:
        out.append({"key": "consent", "severity": "block",
                    "text": "O'quvchi rasmi bor — ota-ona roziligi "
                            "belgilanmagan"})
    if c.status == "ready" and not (c.cta or "").strip():
        out.append({"key": "no_cta", "severity": "warn",
                    "text": "CTA yozilmagan"})
    return out


def _content_out(db: Session, c: models.Content, *, full: bool = False,
                 users: dict | None = None) -> dict:
    users = users if users is not None else {
        u.id: u.full_name for u in db.query(models.User).all()}
    warn = _content_warnings(db, c)
    row = {
        "id": c.id,
        "code": c.content_id or _content_code(c),
        "title": c.title,
        "platform": c.platform,
        "platform_label": roles.PLATFORM_LABELS.get(c.platform or "", "—"),
        "platform_tone": roles.PLATFORM_TONE.get(c.platform or "", "slate"),
        "format": c.fmt,
        "format_label": roles.FORMAT_LABELS.get(c.fmt or "", "—"),
        "pillar": c.pillar,
        "pillar_label": roles.PILLAR_LABELS.get(c.pillar or "", "—"),
        "pillar_tone": roles.PILLAR_TONE.get(c.pillar or "", "slate"),
        "goal": c.goal,
        "goal_label": roles.GOAL_LABELS.get(c.goal or "", "—"),
        "goal_metric": roles.GOAL_METRIC_LABELS.get(
            roles.GOAL_METRIC.get(c.goal or "", ""), "—"),
        "funnel": c.funnel,
        "funnel_label": roles.FUNNEL_LABELS.get(c.funnel or "", "—"),
        "branch": c.branch.name if c.branch else None,
        "branch_id": c.branch_id,
        "course": c.course,
        "campaign_id": c.campaign_id,
        "status": c.status,
        "status_label": roles.CONTENT_STATUS_LABELS.get(c.status, c.status),
        "tone": roles.CONTENT_STATUS_TONE.get(c.status, "slate"),
        "planned_date": (c.planned_date.isoformat()
                         if c.planned_date else None),
        "planned_time": c.planned_time,
        "published_at": (c.published_at.isoformat()
                         if c.published_at else None),
        "owner": users.get(c.owner_id),
        "owner_id": c.owner_id,
        "approver": users.get(c.approver_id),
        "approver_role": _approver_role(c),
        "approver_role_label": roles.UZ_LABELS.get(_approver_role(c) or "", "—"),
        "priority": c.priority,
        "deadline": c.deadline.isoformat() if c.deadline else None,
        "needs_consent": bool(c.needs_consent),
        "consent_ok": bool(c.consent_ok),
        "post_url": c.post_url,
        "warnings": warn,
        "blocked": any(w["severity"] == "block" for w in warn),
    }
    if not full:
        return row

    row.update({
        "audience": c.audience,
        "problem": c.problem, "message": c.message, "hook": c.hook,
        "location": c.location, "participants": c.participants,
        "props": c.props, "duration": c.duration, "music": c.music,
        "design_format": c.design_format, "cta": c.cta,
        "references": c.references,
        "script": c.script, "caption": c.caption,
        "caption_ru": c.caption_ru, "caption_en": c.caption_en,
        "hashtags": c.hashtags, "story_text": c.story_text,
        "on_video_text": c.on_video_text,
        "utm": c.utm, "short_link": c.short_link,
        "promo_code": c.promo_code,
        "post_external_id": c.post_external_id,
        "note": c.note,
        "team": {
            "copywriter": users.get(c.copywriter_id),
            "designer": users.get(c.designer_id),
            "videographer": users.get(c.videographer_id),
            "editor": users.get(c.editor_id),
        },
        "shots": [{
            "id": s.id, "no": s.order_no, "text": s.text,
            "state": s.state, "note": s.note,
        } for s in sorted(c.shots, key=lambda x: x.order_no)],
        "approvals": [{
            "id": a.id, "role": a.role,
            "role_label": roles.UZ_LABELS.get(a.role or "", "—"),
            "decision": a.decision,
            "decision_label": roles.APPROVAL_LABELS.get(a.decision or "", "—"),
            "tone": roles.APPROVAL_TONE.get(a.decision or "", "slate"),
            "comment": a.comment, "quote": a.quote,
            "by": users.get(a.decided_by),
            "date": a.decided_at.isoformat() if a.decided_at else None,
        } for a in sorted(c.approvals, key=lambda x: -x.id)],
        "versions": [{
            "id": v.id, "field": v.field,
            "old": v.old_value, "new": v.new_value,
            "by": v.changed_by,
            "date": v.created_at.isoformat() if v.created_at else None,
        } for v in sorted(c.versions, key=lambda x: -x.id)[:40]],
    })
    return row


def _content_scope(db: Session, user: models.User, branch_id=None):
    q = db.query(models.Content)
    if branch_id:
        q = q.filter(models.Content.branch_id == branch_id)
    elif user.branch_id and user.role not in roles.ORG_WIDE_ROLES:
        q = q.filter((models.Content.branch_id == user.branch_id)
                     | (models.Content.branch_id.is_(None)))
    return q


