def student_to_trial(student_id: int, db: Session = Depends(get_db),
                     user=Depends(require_role(*roles.FREEZE_ROLES))):
    """Faol o'quvchini sinov darsiga qaytarish."""
    st = db.query(models.Student).get(student_id)
