@app.get("/api/students/{student_id}/parent-link")
def parent_link(student_id: int, db: Session = Depends(get_db),
                user=Depends(require_role(*roles.CASH_ACCESS))):
    """Ota-onaga beriladigan havola. Token taxmin qilib bo'lmaydigan
    tasodifiy satr; kerak bo'lsa yangilash tugmasi bilan almashtiriladi."""
    s = db.query(models.Student).get(student_id)
    if not s:
        raise HTTPException(404, "O'quvchi topilmadi")
    if not s.parent_token:
        import secrets as _sec
        s.parent_token = _sec.token_urlsafe(16)
        db.commit()
    base = os.environ.get("PUBLIC_URL", "https://jony-crm.vercel.app")
    return {"url": f"{base}/parent/{s.parent_token}"}


@app.get("/api/parent/{token}")
def parent_view(token: str, db: Session = Depends(get_db)):
    """Ota-ona ko'radigan ochiq sahifa ma'lumoti: davomat, vazifa,
    balans. Faqat o'qish; token orqali bitta o'quvchi."""
    if not token or len(token) < 10:
        raise HTTPException(404, "Topilmadi")
    s = db.query(models.Student).filter(
        models.Student.parent_token == token).first()
    if not s:
        raise HTTPException(404, "Topilmadi")
    g = db.query(models.Group).get(s.group_id) if s.group_id else None
    today = roles.local_today()
    start = today - timedelta(days=45)
    rows = (db.query(models.Attendance, models.Lesson)
            .join(models.Lesson,
                  models.Attendance.lesson_id == models.Lesson.id)
            .filter(models.Attendance.student_id == s.id,
                    models.Lesson.date >= start,
                    models.Lesson.date <= today)
            .order_by(models.Lesson.date.desc()).limit(24).all())
    att = [{
        "date": ls.date.isoformat(),
        "present": int(a.present or 0),   # 1 keldi, 2 kech, 0 kelmadi
        "homework": a.homework,           # 2 bajardi, 1 qisman, 0 yo'q
    } for a, ls in rows]
    bal = student_balance(db, s.id)
    st_lbl = {"active": "faol", "trial": "sinovda",
              "frozen": "muzlatilgan", "archived": "arxivda"}
    return {
        "name": s.full_name,
        "group": g.name if g else None,
        "lesson_time": g.lesson_time if g else None,
        "status": st_lbl.get(s.status, s.status),
        "balance": bal,
        "attendance": att,
        "frozen_until": s.frozen_until.isoformat()
        if s.frozen_until else None,
    }


# =====================================================================
#  ONLAYN TO'LOV HAVOLASI (Payme / Click)
#
#  Merchant hisobi shartnomasi bo'lsa, Vercel'da PAYME_MERCHANT_ID
#  va/yoki CLICK_MERCHANT_ID + CLICK_SERVICE_ID o'rnatiladi — shunda
#  o'quvchi kartasida "To'lov havolasi" tugmasi paydo bo'ladi.
#  Havola ota-onaga yuboriladi; tushum bankdan kelib tushadi va
#  kassir uni odatdagidek "To'lov qo'shish" bilan qayd etadi.
# =====================================================================
@app.get("/api/students/{student_id}/pay-link")
def pay_link(student_id: int, amount: float = 0,
             db: Session = Depends(get_db),
             user=Depends(require_role(*roles.CASH_ACCESS))):
    s = db.query(models.Student).get(student_id)
    if not s:
        raise HTTPException(404, "O'quvchi topilmadi")
    payme_id = os.environ.get("PAYME_MERCHANT_ID", "").strip()
    click_m = os.environ.get("CLICK_MERCHANT_ID", "").strip()
    click_s = os.environ.get("CLICK_SERVICE_ID", "").strip()
    if not payme_id and not (click_m and click_s):
        return {"enabled": False}
    amt = roles.money(amount) if amount and amount > 0 \
        else roles.money(-student_balance(db, s.id)
                         if student_balance(db, s.id) < 0 else 0)
    links = {}
    if payme_id and amt > 0:
        import base64 as _b64
        raw = f"m={payme_id};ac.student={s.public_id or s.id};a={int(amt * 100)}"
        links["payme"] = ("https://checkout.paycom.uz/"
                          + _b64.b64encode(raw.encode()).decode())
    if click_m and click_s and amt > 0:
        links["click"] = (
            "https://my.click.uz/services/pay"
            f"?service_id={click_s}&merchant_id={click_m}"
            f"&amount={int(amt)}&transaction_param={s.public_id or s.id}")
    return {"enabled": True, "amount": amt, "links": links}


# =====================================================================
#  USTOZLARNI EXCEL'DAN IMPORT QILISH
#
#  Eski platformadan (masalan LC UP) eksport qilingan ro'yxatni bir
#  bosishda ko'chirish. Dublikat himoyasi: bir xil ism yoki bir xil
#  telefon bo'lsa, qator o'tkazib yuboriladi — ikki marta bosilsa ham
#  ro'yxat ikkilanmaydi.
# =====================================================================
@app.post("/api/teachers/import")
def import_teachers(payload: schemas.TeacherImportIn,
                    db: Session = Depends(get_db),
                    user=Depends(require_role(*roles.STAFF_VIEWERS))):
    today = roles.local_today()
    existing = db.query(models.Teacher).all()
    names = {(t.full_name or "").strip().lower() for t in existing}
    phones = set()
    for t in existing:
        d = "".join(ch for ch in (t.phone or "") if ch.isdigit())
        if len(d) >= 9:
            phones.add(d[-9:])

    results, created = [], 0
    for r in payload.rows:
        name = (r.full_name or "").strip()
        if not name:
            continue
        digits = "".join(ch for ch in (r.phone or "") if ch.isdigit())
        tail = digits[-9:] if len(digits) >= 9 else None
        if name.lower() in names:
            results.append({"name": name, "status": "skip",
                            "reason": "bu ism allaqachon bor"})
            continue
        if tail and tail in phones:
            results.append({"name": name, "status": "skip",
                            "reason": "bu telefon allaqachon bor"})
            continue

        # Tug'ilgan sana: LC UP bo'sh joyga eksport kunini yozadi —
        # yosh 14 dan kichik chiqsa, sana yo'q deb hisoblaymiz.
        bdate = None
        if r.birth_date:
            try:
                bdate = date.fromisoformat(str(r.birth_date)[:10])
                if bdate.year > today.year - 14:
                    bdate = None
            except ValueError:
                bdate = None

        t = models.Teacher(
            full_name=name,
            phone=r.phone or None,
            branch_id=payload.branch_id,
            birth_date=bdate,
            hired_date=today,
            is_active=1,
            grade=roles.FIRST_GRADE,
            grade_since=today,
        )
        db.add(t)
        db.flush()
        db.add(models.TeacherGradeEvent(
            teacher_id=t.id, from_grade=None, to_grade=t.grade,
            kind="set", effective_from=today,
            reason="Excel'dan import", decided_by=user.full_name))
        names.add(name.lower())
        if tail:
            phones.add(tail)
        created += 1
        results.append({"name": name, "status": "ok",
                        "note": (r.note or "").strip() or None})
    db.commit()
    audit.log(db, user, entity="teacher", action="import",
              entity_label=f"{created} ta ustoz",
              new_value=created, commit=True)
    return {"created": created, "results": results}


# =====================================================================
#  O'QUVCHILARNI EXCEL'DAN GURUHGA IMPORT QILISH
#
#  LC UP'dan guruh bo'yicha eksport qilingan ro'yxatni bir bosishda
#  ko'chirish. Dublikat himoyasi: shu guruhda bir xil ism yoki bir xil
#  telefon bo'lsa, qator o'tkazib yuboriladi. Sig'im tekshiruvi import
#  uchun YUMSHATILADI — eski tizimdagi guruh shundoq ham to'la bo'lishi
#  mumkin, ko'chirish to'sib qo'yilmasin.
# =====================================================================
@app.post("/api/students/import")
def import_students(payload: schemas.StudentImportIn,
                    db: Session = Depends(get_db),
                    user=Depends(require_role(*roles.FREEZE_ROLES))):
    g = db.query(models.Group).get(payload.group_id)
    if not g:
        raise HTTPException(404, "Guruh topilmadi")
    if user.role not in tuple(roles.ORG_WIDE_ROLES) and user.branch_id \
            and g.branch_id and g.branch_id != user.branch_id:
        raise HTTPException(403, "Bu guruh boshqa filialga tegishli")

    today = roles.local_today()
    existing = db.query(models.Student).filter(
        models.Student.group_id == g.id).all()
    names = {(s.full_name or "").strip().lower() for s in existing}
    phones = set()
    for s in existing:
        d = "".join(ch for ch in (s.phone or "") if ch.isdigit())
        if len(d) >= 9:
            phones.add(d[-9:])

    def _status(txt):
        t = (txt or "").strip().lower()
        if "arxiv" in t or "archiv" in t:
            return "archived"
        if "muzlat" in t or "frozen" in t:
            return "frozen"
        if "sinov" in t or "trial" in t:
            return "trial"
        return "active"

    results, created = [], 0
    for r in payload.rows:
        name = (r.full_name or "").strip()
        if not name:
            continue
        digits = "".join(ch for ch in (r.phone or "") if ch.isdigit())
        tail = digits[-9:] if len(digits) >= 9 else None
        if name.lower() in names:
            results.append({"name": name, "status": "skip",
                            "reason": "bu guruhda allaqachon bor"})
            continue
        if tail and tail in phones:
            results.append({"name": name, "status": "skip",
                            "reason": "bu telefon shu guruhda bor"})
            continue

        # LC UP bo'sh tug'ilgan sanaga eksport kunini yozadi — 4
        # yoshdan kichik chiqsa, sana yo'q deb hisoblaymiz.
        bdate = None
        if r.birth_date:
            try:
                bdate = date.fromisoformat(str(r.birth_date)[:10])
                if bdate.year > today.year - 4:
                    bdate = None
            except ValueError:
                bdate = None

        s = models.Student(
            full_name=name,
            phone=(r.phone or "").strip() or None,
            address=(r.address or "").strip() or None,
            birth_date=bdate,
            group_id=g.id,
            branch_id=g.branch_id,
            status=_status(r.status),
            subject=g.subject,
            level=g.level,
            enrolled_date=today,
        )
        db.add(s)
        names.add(name.lower())
        if tail:
            phones.add(tail)
        created += 1
        results.append({"name": name, "status": "ok"})
    db.commit()
    audit.log(db, user, entity="student", action="import",
              entity_label=f"{g.name}: {created} ta o'quvchi",
              new_value=created, branch_id=g.branch_id, commit=True)
    return {"created": created, "group": g.name, "results": results}
